  where slug in ('madaba-map', 'e2e-demo');
update public.item_media set credit = 'Carole Raddato from FRANKFURT, Germany', license = 'CC BY-SA 2.0', license_url = 'https://creativecommons.org/licenses/by-sa/2.0', source_url = 'https://commons.wikimedia.org/wiki/File:The_Madaba_Map,_part_of_a_floor_mosaic_in_the_early_Byzantine_church_of_Saint_George_depicting_the_Holy_Land_in_the_6th_century_AD,_Madaba,_Jordan_(33798361303).jpg', width = 1600, height = 1060, blur = 'data:image/jpeg;base64,'
